<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { ArrowUpRight, KeyRound, Link2, RefreshCw, RotateCcw, X } from '@lucide/vue'
import { bindAdminUserIdentity,getAdminUserApiKeys,getAdminUserBalanceHistory,getAdminUserPlatformQuotas,getAdminUserUsage,resetAdminUserPlatformQuota,updateAdminUserPlatformQuotas } from '@/api/admin/users'
import type { AdminBalanceHistoryResponse,AdminPlatformQuota,AdminQuotaPlatform,AdminQuotaWindow,AdminUser,AdminUserApiKeysResponse,AdminUserUsageSummary } from '@/api/admin/types'
import { formatCost,formatCount,formatDateTime,formatPlatform } from '@/lib/format'

const props=defineProps<{user:AdminUser|null}>();const emit=defineEmits<{close:[];updated:[user:AdminUser]}>();const loading=ref(false);const issues=ref<string[]>([]);const keys=ref<AdminUserApiKeysResponse|null>(null);const usage=ref<AdminUserUsageSummary|null>(null);const history=ref<AdminBalanceHistoryResponse|null>(null);const quotas=ref<AdminPlatformQuota[]>([]);const identity=reactive({provider_type:'oidc',provider_key:'main',provider_subject:''});const saving=ref('');const message=ref('');const quotaDraft=ref<Record<string,{daily:string;weekly:string;monthly:string}>>({});
const platforms:AdminQuotaPlatform[]=['anthropic','openai','gemini','antigravity','grok'];const quotaRows=computed(()=>platforms.map(platform=>quotas.value.find(q=>q.platform===platform)??{platform,daily_limit_usd:null,weekly_limit_usd:null,monthly_limit_usd:null,daily_usage_usd:0,weekly_usage_usd:0,monthly_usage_usd:0}));function syncDraft(){quotaDraft.value=Object.fromEntries(quotaRows.value.map(q=>[q.platform,{daily:q.daily_limit_usd?.toString()??'',weekly:q.weekly_limit_usd?.toString()??'',monthly:q.monthly_limit_usd?.toString()??''}]))}
async function load(){if(!props.user)return;loading.value=true;issues.value=[];const [k,u,h,q]=await Promise.allSettled([getAdminUserApiKeys(props.user.id),getAdminUserUsage(props.user.id,'month'),getAdminUserBalanceHistory(props.user.id,{page:1,page_size:20}),getAdminUserPlatformQuotas(props.user.id)]);if(k.status==='fulfilled')keys.value=k.value;else issues.value.push('API Key');if(u.status==='fulfilled')usage.value=u.value;else issues.value.push('用量');if(h.status==='fulfilled')history.value=h.value;else issues.value.push('余额记录');if(q.status==='fulfilled'){quotas.value=q.value.platform_quotas;syncDraft()}else issues.value.push('平台额度');loading.value=false}
watch(()=>props.user?.id,()=>{message.value='';void load()},{immediate:true});
async function bindIdentity(){if(!props.user||!identity.provider_subject.trim())return;saving.value='identity';try{await bindAdminUserIdentity(props.user.id,{provider_type:identity.provider_type,provider_key:identity.provider_key,provider_subject:identity.provider_subject.trim()});message.value='身份绑定完成';identity.provider_subject=''}catch(caught){message.value=caught instanceof Error&&caught.message?caught.message:'身份绑定失败'}finally{saving.value=''}}
function nullable(v:string){return v.trim()===''?null:Math.max(0,Number(v)||0)}async function saveQuotas(){if(!props.user)return;saving.value='quotas';try{const payload=platforms.map(platform=>({platform,daily_limit_usd:nullable(quotaDraft.value[platform]?.daily??''),weekly_limit_usd:nullable(quotaDraft.value[platform]?.weekly??''),monthly_limit_usd:nullable(quotaDraft.value[platform]?.monthly??'')}));const data=await updateAdminUserPlatformQuotas(props.user.id,payload);quotas.value=data.platform_quotas;syncDraft();message.value='平台额度已保存'}catch(caught){message.value=caught instanceof Error&&caught.message?caught.message:'额度保存失败'}finally{saving.value=''}}async function resetQuota(platform:AdminQuotaPlatform,window:AdminQuotaWindow){if(!props.user)return;const windowLabel={daily:'日',weekly:'周',monthly:'月'}[window];if(!globalThis.confirm(`确认重置 ${props.user.email} 的 ${formatPlatform(platform)} ${windowLabel}用量？`))return;saving.value=`${platform}-${window}`;try{const data=await resetAdminUserPlatformQuota(props.user.id,platform,window);quotas.value=data.platform_quotas;syncDraft();message.value=`${formatPlatform(platform)} ${windowLabel}用量已重置`}catch(caught){message.value=caught instanceof Error&&caught.message?caught.message:'额度重置失败'}finally{saving.value=''}}
</script>
<template><Transition name="drawer"><div v-if="user" class="backdrop" @mousedown.self="emit('close')"><aside class="detail" data-testid="user-detail"><header><div><h2>{{ user.username }}</h2><p>{{ user.email }}</p></div><button type="button" @click="emit('close')"><X :size="18" /></button></header><p v-if="issues.length" class="warning">部分数据不可用：{{ issues.join('、') }}</p><p v-if="message" class="message">{{ message }}</p><div v-if="loading" class="loading"><i v-for="n in 7" :key="n" /></div><template v-else>
<section class="metrics"><div><span>近 30 天请求</span><strong>{{ formatCount(usage?.total_requests) }}</strong></div><div><span>Token</span><strong>{{ formatCount(usage?.total_tokens) }}</strong></div><div><span>消费</span><strong>{{ formatCost(usage?.total_cost) }}</strong></div><div><span>当前余额</span><strong>{{ formatCost(user.balance) }}</strong></div></section>
<section class="panel"><h3><KeyRound :size="16" />API Key</h3><div v-if="!keys?.items.length" class="empty">暂无 API Key</div><div v-for="key in keys?.items" :key="key.id" class="key-row"><div><strong>{{ key.name }}</strong><span>{{ key.status }}</span></div><span>已用 {{ formatCost(key.quota_used) }}</span></div></section>
<section class="panel"><h3><ArrowUpRight :size="16" />余额记录</h3><div v-if="!history?.items.length" class="empty">暂无记录</div><div v-for="item in history?.items.slice(0,5)" :key="item.id" class="history-row"><div><strong>{{ item.type }}</strong><span>{{ item.notes||'无备注' }}</span></div><em>{{ item.value>0?'+':'' }}{{ formatCost(item.value) }}</em><span>{{ formatDateTime(item.created_at) }}</span></div></section>
<section class="panel"><h3><Link2 :size="16" />绑定登录身份</h3><form class="identity-form" @submit.prevent="bindIdentity"><select v-model="identity.provider_type"><option value="oidc">OIDC</option><option value="linuxdo">LinuxDo</option><option value="github">GitHub</option><option value="google">Google</option><option value="wechat">微信</option><option value="dingtalk">钉钉</option></select><input v-model="identity.provider_key" placeholder="Provider Key" /><input v-model="identity.provider_subject" placeholder="Provider Subject" /><button type="submit">绑定</button></form></section>
<section class="panel quota-panel"><div class="panel-title"><h3><RefreshCw :size="16" />平台额度</h3><button type="button" :disabled="saving==='quotas'" @click="saveQuotas">保存额度</button></div><div class="quota-head"><span>平台</span><span>日限额</span><span>周限额</span><span>月限额</span><span>日 / 周 / 月用量</span></div><div v-for="quota in quotaRows" :key="quota.platform" class="quota-row"><strong>{{ formatPlatform(quota.platform) }}</strong><input v-model="quotaDraft[quota.platform]!.daily" placeholder="不限" /><input v-model="quotaDraft[quota.platform]!.weekly" placeholder="不限" /><input v-model="quotaDraft[quota.platform]!.monthly" placeholder="不限" /><div class="quota-usage"><span><small>日 {{ formatCost(quota.daily_usage_usd) }}</small><button type="button" title="重置日用量" :data-testid="`reset-quota-${quota.platform}-daily`" :disabled="saving===`${quota.platform}-daily`" @click="resetQuota(quota.platform,'daily')"><RotateCcw :size="12" /></button></span><span><small>周 {{ formatCost(quota.weekly_usage_usd) }}</small><button type="button" title="重置周用量" :data-testid="`reset-quota-${quota.platform}-weekly`" :disabled="saving===`${quota.platform}-weekly`" @click="resetQuota(quota.platform,'weekly')"><RotateCcw :size="12" /></button></span><span><small>月 {{ formatCost(quota.monthly_usage_usd) }}</small><button type="button" title="重置月用量" :data-testid="`reset-quota-${quota.platform}-monthly`" :disabled="saving===`${quota.platform}-monthly`" @click="resetQuota(quota.platform,'monthly')"><RotateCcw :size="12" /></button></span></div></div></section>
</template></aside></div></Transition></template>
<style scoped>
.backdrop{position:fixed;z-index:90;inset:0;background:rgba(31,42,58,.16);backdrop-filter:blur(5px)}.detail{position:absolute;top:0;right:0;width:min(650px,72vw);min-width:520px;height:100%;padding:26px;overflow:auto;background:rgba(249,251,254,.99);border-left:1px solid rgba(215,223,234,.9);box-shadow:-18px 0 54px rgba(32,47,68,.16)}header{display:flex;align-items:center;justify-content:space-between;gap:16px}h2{margin:0;font-size:20px}header p{margin:4px 0 0;color:var(--text-tertiary);font-size:12px}header button{display:grid;width:32px;height:32px;border:0;background:transparent;color:var(--text-tertiary);cursor:pointer;place-items:center}.warning,.message{padding:9px 11px;border-radius:7px;font-size:12px}.warning{background:#fff8e8;border:1px solid #f0dda9;color:#8a641b}.message{background:#edf5ff;border:1px solid #d3e3f8;color:#3f67a2}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:18px}.metrics>div{display:grid;gap:5px;padding:12px;background:white;border:1px solid var(--border-subtle);border-radius:7px}.metrics span{color:var(--text-tertiary);font-size:10px}.metrics strong{font-family:var(--font-data);font-size:15px}.panel{margin-top:14px;padding:15px;background:white;border:1px solid var(--border-subtle);border-radius:8px}.panel h3{display:flex;align-items:center;gap:7px;margin:0 0 11px;font-size:13px}.balance-form,.identity-form{display:grid;grid-template-columns:90px 100px minmax(0,1fr) 36px;gap:7px}.identity-form{grid-template-columns:100px 120px minmax(0,1fr) 58px}input,select{min-width:0;height:35px;padding:0 9px;border:1px solid var(--border-subtle);border-radius:6px;background:white;color:var(--text-primary);font:inherit;font-size:11px;outline:0}.balance-form button,.identity-form button,.panel-title button{display:grid;border:0;border-radius:6px;background:var(--accent);color:white;cursor:pointer;place-items:center}.key-row,.history-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:10px;min-height:42px;border-top:1px solid var(--border-subtle);font-size:11px}.key-row:first-of-type,.history-row:first-of-type{border-top:0}.key-row>div,.history-row>div{display:grid;gap:3px}.key-row span,.history-row span{color:var(--text-tertiary)}.history-row{grid-template-columns:minmax(0,1fr) 70px 120px}.history-row em{font-family:var(--font-data);font-style:normal}.empty{padding:16px;color:var(--text-tertiary);font-size:12px;text-align:center}.panel-title{display:flex;align-items:center;justify-content:space-between}.panel-title h3{margin:0}.panel-title button{height:30px;padding:0 10px}.quota-head,.quota-row{display:grid;grid-template-columns:85px repeat(3,minmax(62px,1fr)) 100px;align-items:center;gap:7px;margin-top:9px}.quota-head{color:var(--text-tertiary);font-size:10px}.quota-row strong{font-size:11px}.quota-row input{height:31px}.quota-row>div{display:flex;align-items:center;justify-content:space-between;gap:4px;color:var(--text-secondary);font-size:10px}.quota-row>div button{display:grid;width:25px;height:25px;padding:0;border:0;border-radius:5px;background:var(--bg-base);color:var(--text-tertiary);cursor:pointer;place-items:center}.loading{display:grid;gap:10px;margin-top:20px}.loading i{height:54px;background:#edf1f5;border-radius:7px}.spinning{animation:spin .75s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.drawer-enter-active,.drawer-leave-active{transition:opacity 200ms}.drawer-enter-active .detail,.drawer-leave-active .detail{transition:transform 220ms var(--motion-ease-out)}.drawer-enter-from,.drawer-leave-to{opacity:0}.drawer-enter-from .detail,.drawer-leave-to .detail{transform:translateX(28px)}
</style>
